/* From Uiverse.io by ParasSalunke  - Tags: card */
.__UIV_SCOPE__ .music-card {
  cursor: pointer;
  width: 100%;
  max-width: 340px;
  margin: 0 auto;
  background-color: #f7f7f7;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  border-radius: 10px;
  overflow: hidden;
  transition: transform 0.3s ease;
}

.__UIV_SCOPE__ .music-card:hover {
  transform: translateY(-5px);
}

.__UIV_SCOPE__ .card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px;
  background-color: #fff;
}

.__UIV_SCOPE__ .track-info {
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .track-icon {
  height: 24px;
  width: 24px;
  color: #f59e0b;
}

.__UIV_SCOPE__ .track-details {
  margin-left: 12px;
}

.__UIV_SCOPE__ .track-title {
  font-size: 1.2rem;
  font-weight: 600;
  color: #333;
}

.__UIV_SCOPE__ .track-artist {
  font-size: 0.9rem;
  color: #666;
}

.__UIV_SCOPE__ .card-icons {
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .icon-heart {
  height: 24px;
  width: 24px;
  color: #ef4444;
  cursor: pointer;
}

.__UIV_SCOPE__ .icon-star {
  height: 24px;
  width: 24px;
  color: #9ca3af;
  margin-left: 16px;
  cursor: pointer;
}

.__UIV_SCOPE__ .icon-star:hover {
  color: #fbbf24;
}

.__UIV_SCOPE__ .progress-container {
  position: relative;
  margin: 16px 16px 8px 16px;
  height: 6px;
  background-color: #e5e7eb;
  border-radius: 3px;
  overflow: hidden;
}

.__UIV_SCOPE__ .progress-bar {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 60%;
  background-color: #f59e0b;
  border-radius: 3px;
}

.__UIV_SCOPE__ .progress-time {
  display: flex;
  justify-content: space-between;
  padding: 0 16px 16px 16px;
  font-size: 0.85rem;
  color: #6b7280;
}
